local Players = game:GetService("Players")local Player = Players.LocalPlayerlocal ScreenGui = Instance.new("ScreenGui")local MenuFrame = Instance.new("Frame")local ToggleButton = Instance.new("TextButton")local MainButton = Instance.new("TextButton")  -- Nút chính để bật tắt menulocal ImageLabel = Instance.new("ImageLabel")  -- Thêm logo vào nút-- Thiết lập GUIScreenGui.Parent = Player:WaitForChild("PlayerGui")MenuFrame.Size = UDim2.new(0, 300, 0, 200)MenuFrame.Position = UDim2.new(0.5, -150, 0.5, -100)MenuFrame.BackgroundColor3 = Color3.new(1, 1, 1)MenuFrame.BorderSizePixel = 0MenuFrame.Visible = false  -- Bắt đầu với menu không hiển thịMenuFrame.Parent = ScreenGui-- Thiết lập Nút hình trònMainButton.Size = UDim2.new(0, 100, 0, 100)MainButton.Position = UDim2.new(0.5, -50, 0.1, 0)MainButton.BackgroundColor3 = Color3.new(0, 0, 0)  -- Màu nền của nútMainButton.Text = "Taidepzai hub"MainButton.AutoButtonColor = falseMainButton.Parent = ScreenGui-- Tạo logo cho nútImageLabel.Size = UDim2.new(1, 0, 1, 0)ImageLabel.Image = "rbxassetid://96693216224872" -- Thay YOUR_IMAGE_ID bằng ID hình ảnh của logo bạn muốn sử dụngImageLabel.Parent = MainButton-- Tạo góc tròn cho nútMainButton.ClipsDescendants = trueMainButton.BackgroundTransparency = 1  -- Để hiển thị hình ảnh bên tronglocal colors = {    Color3.fromRGB(255, 0, 0),    Color3.fromRGB(255, 127, 0),    Color3.fromRGB(255, 255, 0),    Color3.fromRGB(0, 255, 0),    Color3.fromRGB(0, 0, 255),    Color3.fromRGB(75, 0, 130),    Color3.fromRGB(148, 0, 211),}local menuVisible = false-- Hàm để thay đổi màu viềnlocal function changeBorderColor()    local currentIndex = 1    while true do        if menuVisible then            MenuFrame.BorderColor3 = colors[currentIndex]            currentIndex = currentIndex + 1            if currentIndex > #colors then                currentIndex = 1            end        end        wait(0.5)  -- Thay đổi tốc độ chuyển màu ở đây    endend-- Hàm để hiệu ứng quay trònlocal function spinButton()    while true do        MainButton.RotVelocity = Vector3.new(0, 0, 360)        wait(0.1)    endend-- Nút Toggle - để ẩn/hiện menuMainButton.MouseButton1Click:Connect(function()    menuVisible = not menuVisible    MenuFrame.Visible = menuVisibleend)-- Bắt đầu thay đổi màu và hiệu ứngchangeBorderColor()spinButton()